var dataInput = input.get('data');
var schemaInput = input.get('schema');
var strictMode = input.get('strictMode') === 'true';

if (!dataInput) {
    output.set('HasErrors', true);
    output.set('ErrorMessage', 'Data input is required');
    output.set('IsValid', false);
    tags.trigger('error');
} else if (!schemaInput) {
    output.set('HasErrors', true);
    output.set('ErrorMessage', 'Schema is required');
    output.set('IsValid', false);
    tags.trigger('error');
} else {
    try {
        var data = json.parse(dataInput);
        var schema = json.parse(schemaInput);
        var errors = [];

        function getType(val) {
            if (val === null) return 'null';
            if (Array.isArray(val)) return 'array';
            return typeof val;
        }

        function validate(obj, rules, path) {
            path = path || '$';

            if (rules.type) {
                var actualType = getType(obj);
                var expectedTypes = Array.isArray(rules.type) ? rules.type : [rules.type];
                var typeMatch = false;
                for (var t = 0; t < expectedTypes.length; t++) {
                    if (actualType === expectedTypes[t]) typeMatch = true;
                    if (expectedTypes[t] === 'integer' && actualType === 'number' && obj % 1 === 0) typeMatch = true;
                }
                if (!typeMatch) {
                    errors.push({path: path, error: 'Expected ' + expectedTypes.join('|') + ', got ' + actualType});
                }
            }

            if (rules.required && Array.isArray(rules.required) && getType(obj) === 'object') {
                for (var r = 0; r < rules.required.length; r++) {
                    var reqField = rules.required[r];
                    if (obj[reqField] === undefined) {
                        errors.push({path: path + '.' + reqField, error: 'Required field missing'});
                    }
                }
            }

            if (rules.properties && getType(obj) === 'object') {
                var propKeys = Object.keys(rules.properties);
                for (var p = 0; p < propKeys.length; p++) {
                    var propName = propKeys[p];
                    if (obj[propName] !== undefined) {
                        validate(obj[propName], rules.properties[propName], path + '.' + propName);
                    }
                }

                if (strictMode) {
                    var dataKeys = Object.keys(obj);
                    for (var d = 0; d < dataKeys.length; d++) {
                        if (!rules.properties[dataKeys[d]]) {
                            errors.push({path: path + '.' + dataKeys[d], error: 'Unknown property (strict mode)'});
                        }
                    }
                }
            }

            if (rules.items && Array.isArray(obj)) {
                for (var i = 0; i < obj.length; i++) {
                    validate(obj[i], rules.items, path + '[' + i + ']');
                }
            }

            if (getType(obj) === 'number') {
                if (rules.minimum !== undefined && obj < rules.minimum) {
                    errors.push({path: path, error: 'Value ' + obj + ' below minimum ' + rules.minimum});
                }
                if (rules.maximum !== undefined && obj > rules.maximum) {
                    errors.push({path: path, error: 'Value ' + obj + ' above maximum ' + rules.maximum});
                }
            }

            if (getType(obj) === 'string') {
                if (rules.minLength !== undefined && obj.length < rules.minLength) {
                    errors.push({path: path, error: 'String length ' + obj.length + ' below minimum ' + rules.minLength});
                }
                if (rules.maxLength !== undefined && obj.length > rules.maxLength) {
                    errors.push({path: path, error: 'String length ' + obj.length + ' above maximum ' + rules.maxLength});
                }
                if (rules.pattern) {
                    var regex = new RegExp(rules.pattern);
                    if (!regex.test(obj)) {
                        errors.push({path: path, error: 'Does not match pattern ' + rules.pattern});
                    }
                }
                if (rules.enum && Array.isArray(rules.enum)) {
                    if (rules.enum.indexOf(obj) === -1) {
                        errors.push({path: path, error: 'Value not in enum: ' + rules.enum.join(', ')});
                    }
                }
                if (rules.format) {
                    if (rules.format === 'email' && !/^[^@]+@[^@]+\.[^@]+$/.test(obj)) {
                        errors.push({path: path, error: 'Invalid email format'});
                    }
                    if (rules.format === 'uri' && !/^https?:\/\/.+/.test(obj)) {
                        errors.push({path: path, error: 'Invalid URI format'});
                    }
                    if (rules.format === 'date' && isNaN(Date.parse(obj))) {
                        errors.push({path: path, error: 'Invalid date format'});
                    }
                }
            }

            if (Array.isArray(obj)) {
                if (rules.minItems !== undefined && obj.length < rules.minItems) {
                    errors.push({path: path, error: 'Array length ' + obj.length + ' below minimum ' + rules.minItems});
                }
                if (rules.maxItems !== undefined && obj.length > rules.maxItems) {
                    errors.push({path: path, error: 'Array length ' + obj.length + ' above maximum ' + rules.maxItems});
                }
            }
        }

        validate(data, schema, '$');

        var isValid = errors.length === 0;

        output.set('IsValid', isValid);
        output.set('ErrorCount', errors.length);
        output.set('Errors', json.stringify(errors));
        output.set('FirstError', errors.length > 0 ? errors[0].path + ': ' + errors[0].error : '');
        output.set('Data', json.stringify(data));
        output.set('HasErrors', false);
        output.set('ErrorMessage', '');

        log.info('Validation ' + (isValid ? 'passed' : 'failed: ' + errors.length + ' errors'));

        if (isValid) {
            tags.trigger('valid');
        } else {
            tags.trigger('invalid');
        }
        tags.trigger('success');

    } catch (ex) {
        log.error('Validation failed: ' + ex.message);
        output.set('HasErrors', true);
        output.set('ErrorMessage', ex.message);
        output.set('IsValid', false);
        tags.trigger('error');
    }
}
